-- Phase 35.1: the answer library (docs/data-model.md `answers`; docs/screens.md "## Phase 35").
-- Generated by drizzle-kit, then by hand: the starters, the setting function and the comments.
-- - answers: the firm's own automatic answers (name, example phrases one a line, the words with
--   fill-ins from a fixed list, on or off, who last changed it). Never deleted (TABLE_ACCESS:
--   SELECT, INSERT, and UPDATE of the editable columns only); RLS and the tenant policy as every
--   firm table; at most one of each starter per firm (answers_firm_id_starter_key_idx).
-- - messages.answer_id, inbound_emails.answer_id: which answer went (composite FKs); a new intent
--   'answer' on both (answer_id set exactly when the intent is 'answer'); email_replies.template
--   'answer' for the automatic email that carries one.
-- - The five starters, switched off, for every firm here now (new firms get them from
--   src/lib/answers/starters.ts, whose words these are: tests/unit/answers.library.test.ts).
-- - app_set_firm_setting() also accepts answers.app, answers.texts and answers.email ('true' or
--   'false', stored as booleans under settings.answers). Every other key exactly as in 0047. Same
--   name, owner and grants (CREATE OR REPLACE keeps them).
CREATE TABLE "answers" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"firm_id" uuid NOT NULL,
	"name" text NOT NULL,
	"examples" text DEFAULT '' NOT NULL,
	"body" text NOT NULL,
	"is_on" boolean DEFAULT false NOT NULL,
	"starter_key" text,
	"updated_by" uuid,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "answers_firm_id_id_key" UNIQUE("firm_id","id"),
	CONSTRAINT "answers_name_length" CHECK (char_length("answers"."name") between 1 and 60),
	CONSTRAINT "answers_body_length" CHECK (char_length("answers"."body") between 1 and 600),
	CONSTRAINT "answers_examples_shape" CHECK (char_length("answers"."examples") <= 1100
        and char_length("answers"."examples") - char_length(replace("answers"."examples", E'\n', '')) <= 9
        and "answers"."examples" !~ '[^\n]{101}'),
	CONSTRAINT "answers_starter_key_format" CHECK ("answers"."starter_key" ~ '^[a-z_]{1,40}$')
);
