-- The five starters for every firm, switched off until someone reads them (no updated_by: the
-- system). Forced RLS binds the owner on firms' tables (once applied), so each firm is set in turn
-- (as 0043 does), and the setting is cleared at the end.
DO $$
DECLARE
  f record;
BEGIN
  FOR f IN SELECT id FROM public.firms ORDER BY id LOOP
    PERFORM set_config('app.current_firm_id', f.id::text, true);
    INSERT INTO public.answers (firm_id, name, examples, body, is_on, starter_key)
    SELECT f.id, s.name, s.examples, s.body, false, s.starter_key
      FROM (VALUES
        ('pay_day', 'Pay day',
         E'when do we get paid\nwhen will i get paid\nis pay this friday\nwhen is payday',
         'Your next pay day is {next_pay_day}, for shifts {pay_cycle}. Your hours and rates: {pay_link}'),
        ('what_to_wear', 'What to wear',
         E'what do i wear\nwhat uniform\ndo i need my hi vis',
         'For {next_shift}: {next_shift_instructions}'),
        ('renewing_licence', 'Renewing a licence',
         E'my licence runs out\nmy badge runs out\nnew licence',
         'Your {licence_expiry}. When you have the new one, add it on Profile: {profile_link}. The office checks it.'),
        ('parking', 'Parking',
         E'where do i park\nis there parking',
         'Each shift says where to park in its instructions. If it doesn''t, staff parking isn''t provided: please use public transport or a nearby car park.'),
        ('office_hours', 'Office hours',
         E'is anyone in\nwhat time is the office open',
         'The office is open Monday to Friday, 9:00 to 17:00. Out of hours, questions about your shifts, cancelling and pay are answered here straight away.')
      ) AS s (starter_key, name, examples, body)
    ON CONFLICT DO NOTHING;
  END LOOP;
  PERFORM set_config('app.current_firm_id', '', true);
END $$;
